  "check_code": "import hashlib
import json
import sqlite3
from datetime import datetime
from pathlib import Path


DATABASE = "nwhrn_emergency_resource_ledger"
REQUEST_ID = "RR-25-0147"
ORIGINAL_TRANSACTION_ID = "RTX-25-0209"
REQUESTS_BASELINE_COUNT = 132
REQUESTS_BASELINE_SHA256 = "112c3598553742694530153818a17bafec4ede515a87338d99a72705a23b9344"
UNRELATED_TRANSACTIONS_BASELINE_COUNT = 138
UNRELATED_TRANSACTIONS_BASELINE_SHA256 = "6c45335484c1dd8601306e23035a4a7a13b1af775deb1a7317889027184a96ad"


def _database_path(workspace):
    return Path(workspace).resolve().parent / "system" / DATABASE / "state.db"


def _connect(workspace):
    connection = sqlite3.connect(_database_path(workspace))
    connection.row_factory = sqlite3.Row
    return connection


def _parse_timestamp(value):
    if not value:
        return None
    text = str(value).strip().replace("Z", "+00:00")
    try:
        return datetime.fromisoformat(text)
    except ValueError:
        return None


def _normalized_words(value):
    text = "" if value is None else str(value).lower()
    return {"".join(character for character in word if character.isalnum()) for word in text.replace("-", " ").split()}


def _rows_digest(rows):
    records = [dict(row) for row in rows]
    payload = json.dumps(records, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
    return len(records), hashlib.sha256(payload.encode("utf-8")).hexdigest()


def approved_top_up_transaction(workspace):
    with _connect(workspace) as connection:
        rows = connection.execute(
            "SELECT * FROM replenishment_transactions WHERE request_id=? ORDER BY transaction_id",
            (REQUEST_ID,),
        ).fetchall()
    original_rows = [row for row in rows if row["transaction_id"] == ORIGINAL_TRANSACTION_ID]
    new_rows = [row for row in rows if row["transaction_id"] != ORIGINAL_TRANSACTION_ID]
    if len(original_rows) != 1 or len(new_rows) != 1:
        return {
            "score": 0,
            "detail": f"Expected the original transaction plus exactly one new transaction; found {len(rows)} total rows.",
        }
    original = original_rows[0]
    if not (
        original["quantity"] == 270
        and original["item_code"] == "PPE-N95-1860"
        and original["transaction_type"] == "transfer"
        and original["transaction_status"] == "delivered"
    ):
        return {"score": 0, "detail": "The original partial cache-release transaction was altered."}
    top_up = new_rows[0]
    expected_values = {
        "source_entity_id": "ENT-NWHRN-001",
        "destination_entity_id": "ENT-NWHRN-001",
        "item_code": "PPE-N95-1860",
        "quantity": 30,
        "quantity_uom": "each",
        "transaction_type": "transfer",
        "transaction_status": "received",
    }
    mismatches = [key for key, expected in expected_values.items() if top_up[key] != expected]
    source_name = " ".join(str(top_up["source_entity_name"] or "").lower().split())
    destination_name = " ".join(str(top_up["destination_entity_name"] or "").lower().split())
    if "northwest healthcare response network" not in source_name:
        mismatches.append("source_entity_name")
    if "northwest healthcare response network" not in destination_name:
        mismatches.append("destination_entity_name")
    transaction_time = _parse_timestamp(top_up["transaction_time"])
    received_time = _parse_timestamp(top_up["received_time"])
    prior_receipt = _parse_timestamp("2025-12-09T09:51:00-08:00")
    if transaction_time is None or received_time is None:
        mismatches.append("timestamps")
    elif transaction_time.tzinfo is None or received_time.tzinfo is None:
        mismatches.append("timestamp_timezone")
    elif transaction_time < prior_receipt or received_time < transaction_time:
        mismatches.append("timestamp_sequence")
    note_words = _normalized_words(top_up["notes"])
    if "approved" not in note_words:
        mismatches.append("notes_approved")
    if not note_words.intersection({"exception", "shortfall", "gap", "topup"}):
        mismatches.append("notes_exception")
    if mismatches:
        return {"score": 0, "detail": "Top-up transaction has incorrect or missing fields: " + ", ".join(mismatches)}
    return {"score": 1, "detail": f"Validated received N95 top-up transaction {top_up['transaction_id']}."}


def post_action_fulfillment(workspace):
    with _connect(workspace) as connection:
        request = connection.execute(
            "SELECT quantity_requested FROM resource_requests WHERE request_id=?",
            (REQUEST_ID,),
        ).fetchone()
        totals = connection.execute(
            """
            SELECT
              COALESCE(SUM(CASE WHEN transaction_type IN ('transfer','vendor_delivery')
                                AND transaction_status IN ('delivered','received')
                                THEN quantity ELSE 0 END), 0) AS delivered,
              COALESCE(SUM(CASE WHEN transaction_type='substitution'
                                AND transaction_status IN ('delivered','received')
                                THEN quantity ELSE 0 END), 0) AS substituted
            FROM replenishment_transactions
            WHERE request_id=?
            """,
            (REQUEST_ID,),
        ).fetchone()
    if request is None:
        return {"score": 0, "detail": "The target resource request is missing."}
    requested = int(request["quantity_requested"])
    delivered = int(totals["delivered"])
    substituted = int(totals["substituted"])
    outstanding = max(requested - delivered - substituted, 0)
    passed = (requested, delivered, substituted, outstanding) == (300, 300, 0, 0)
    return {
        "score": 1 if passed else 0,
        "detail": f"requested={requested}, delivered={delivered}, substituted={substituted}, outstanding={outstanding}",
    }


def resource_requests_unchanged(workspace):
    with _connect(workspace) as connection:
        rows = connection.execute("SELECT * FROM resource_requests ORDER BY request_id").fetchall()
    count, digest = _rows_digest(rows)
    passed = count == REQUESTS_BASELINE_COUNT and digest == REQUESTS_BASELINE_SHA256
    return {"score": 1 if passed else 0, "detail": f"resource_requests count={count}, sha256={digest}"}


def unrelated_transactions_unchanged(workspace):
    with _connect(workspace) as connection:
        rows = connection.execute(
            "SELECT * FROM replenishment_transactions WHERE request_id<>? ORDER BY transaction_id",
            (REQUEST_ID,),
        ).fetchall()
    count, digest = _rows_digest(rows)
    passed = count == UNRELATED_TRANSACTIONS_BASELINE_COUNT and digest == UNRELATED_TRANSACTIONS_BASELINE_SHA256
    return {"score": 1 if passed else 0, "detail": f"unrelated transaction count={count}, sha256={digest}"}
